let VIEW='follow',railMode='tasks',railOpen=false,formType='',selId=null,pageN=0,sort={k:'cargo',dir:1},REVIEW=null;const PER=50;
const F={q:'',buyer:'',merch:'',stage:'',lab:'',bom:'',quick:'',tst:'',month:'',from:'',to:'',pstat:''};
const QUICK={order:{l:'Order entry review',f:j=>j.wf.order==='review'},cad:{l:'CAD consumption',f:j=>j.wf.cad==='ready'},ie:{l:'IE bulletin',f:j=>j.wf.ie==='ready'},thread:{l:'Thread consumption',f:j=>j.wf.thread==='ready'},fabric:{l:'Fabric order sheet',f:j=>j.wf.fabric==='ready'},tna:{l:'Planning pending',f:j=>j.wf.tna==='ready'||j.wf.tna==='sent'},file:{l:'File handover due',f:j=>j.wf.file==='ready'},preprod:{l:'Pre-production in progress',f:j=>j.wf.preprod==='ready'},sizeset:{l:'Size set in progress',f:j=>j.wf.sizeset==='ready'},ppm:{l:'PP meeting to call',f:j=>j.wf.ppm==='ready'},delay:{l:'Shipment date passed',f:j=>!!j.cargo&&j.cargo<TODAY}};
function match(j,skip){const q=F.q.toLowerCase();return seeJob(j)&&(!q||(j.jobCode+' '+j.style+' '+j.merch+' '+j.buyerName+' '+(j.styleName||'')).toLowerCase().includes(q))&&(skip==='buyer'||!F.buyer||j.buyerName===F.buyer)&&(!F.merch||j.merch===F.merch)&&(!F.stage||j.stage===F.stage)&&(!F.lab||({'Pending':j.labS.k==='wait'||j.labS.k==='late','All approved':j.labS.k==='done','Not started':j.labS.k==='none'})[F.lab])&&(!F.bom||j.bomV===F.bom)&&(!F.month||(j.cargo||'').slice(0,7)===F.month)&&(!F.from||(j.cargo&&j.cargo>=F.from))&&(!F.to||(j.cargo&&j.cargo<=F.to))&&(!F.pstat||j.pstat===F.pstat)&&(skip==='quick'||!F.quick||QUICK[F.quick].f(j))}
function sel(id,label,opts,val,labf){return `<select id="${id}" aria-label="${label}"><option value="">${label}</option>${opts.map(o=>`<option value="${esc(o)}" ${o===val?'selected':''}>${esc(labf?labf(o):o)}</option>`).join('')}</select>`}
function stepPill(j,k){const s=j.wf[k];const M={order:{review:['late','Review pending'],done:['done','Confirmed']},cad:{wait:['none','Not yet'],ready:['wait','Pending'],done:['done','Done']},ie:{wait:['none','Not yet'],ready:['wait','Pending'],done:['done','Done']},thread:{wait:['none','Not yet'],ready:['wait','Pending'],done:['done','Done']},fabric:{wait:['none','Not yet'],ready:['wait','Due'],sent:['run','With Planning'],done:['done','Approved']},tna:{wait:['none','Not yet'],ready:['wait','Due'],sent:['run','With Planning'],done:['done','Approved']},file:{wait:['none','Not yet'],ready:['wait','Due'],done:['done','Handed over']},preprod:{wait:['none','Not yet'],ready:['run','In progress'],done:['done','Done']},sizeset:{wait:['none','Not yet'],ready:['run','In progress'],done:['done','OK']},ppm:{wait:['none','Not yet'],ready:['wait','Call it'],done:['done','Called']}};const x=(M[k]&&M[k][s])||['none','—'];return pill(x[0],x[1])}
