 if(k==='itemDesc'||k==='peDesc')return j[k]?`<span title="${esc(j[k])}" style="display:inline-block;max-width:170px;overflow:hidden;text-overflow:ellipsis;vertical-align:bottom">${esc(j[k])}</span>`:'<span class="muted">—</span>';
 if(k==='pe')return esc(j.pe||'')||'<span class="muted">—</span>';
