 if(k==='trimOV'){if(!j.demo&&canEdit(j))return `<select class="inl ${TRIMOST[j.trimOV]}" data-j="${esc(j.id)}" data-f="trimO" aria-label="Trims ordering">${TRIMO.map(x=>`<option ${x===j.trimOV?'selected':''}>${x}</option>`).join('')}</select>`;return pill(TRIMOST[j.trimOV],j.trimOV)}
 if(k==='trimIV')return pill(TRIMIST[j.trimIV],j.trimIV);
 if(k==='labS'){if(!j.demo&&canEdit(j))return `<select class="inl ${LABST[j.labV]}" data-j="${esc(j.id)}" data-f="lab" aria-label="Lab dip">${LAB.map(x=>`<option ${x===j.labV?'selected':''}>${x}</option>`).join('')}</select>`;return pill(j.labS.k,j.labS.t)}
 if(k==='packV'){if(canEdit(j))return `<select class="inl ${PACKST[j.packV]}" data-j="${esc(j.id)}" data-f="pack" aria-label="Packing list">${PACK.map(x=>`<option ${x===j.packV?'selected':''}>${x}</option>`).join('')}</select>`;return pill(PACKST[j.packV],j.packV)}
 if(k==='pp'){const t=String(j.pp||'').toLowerCase();if(!t)return '<span class="st none">—</span>';const ok=t.includes('ok')||t.includes('apv');return pill(ok?'done':t.includes('cmmts')?'wait':t.includes('due')?'late':'run',j.pp.replace(/\s+/g,' ').trim())}
 if(['tFile','tTrims','tPP','tFab','tCut','tSewS','tSewE','cargo'].includes(k)){const v=j[k];return v?(k==='cargo'&&j.risk?`<span style="color:var(--bad)">${fmt(v)}</span>`:fmt(v)):'<span class="muted">—</span>'}
