 G('fmerch').onchange=e=>{F.merch=e.target.value;pageN=0;render()};G('fstage').onchange=e=>{F.stage=e.target.value;pageN=0;render()};G('flab').onchange=e=>{F.lab=e.target.value;pageN=0;render()};G('fbom').onchange=e=>{F.bom=e.target.value;pageN=0;render()};G('fmonth').onchange=e=>{F.month=e.target.value;pageN=0;render()};G('ffrom').onchange=e=>{F.from=e.target.value;pageN=0;render()};G('fto').onchange=e=>{F.to=e.target.value;pageN=0;render()};
 G('fclear').onclick=()=>{Object.keys(F).forEach(k=>F[k]='');pageN=0;render()};
 m.querySelectorAll('[data-clr]').forEach(b=>b.onclick=()=>{F[b.dataset.clr]='';render()});
 m.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>{const k=b.dataset.q;F.quick=F.quick===k?'':k;pageN=0;render()});
