const overlay=G('overlay');
function openRail(mode,id,ft){railMode=mode;selId=id||null;formType=ft||'';railOpen=true;render()}
function closeRail(){railMode='tasks';selId=null;formType='';REVIEW=null;railOpen=false;render()}
overlay.onclick=closeRail;document.addEventListener('keydown',e=>{if(e.key==='Escape'&&railOpen&&mobile())closeRail()});
const FORMNAME={preprod:'Pre-production',sizeset:'Size set',ppm:'PP meeting',order:'Order review',cad:'CAD consumption',ie:'IE bulletin',thread:'Thread consumption',fabric:'Fabric order sheet',tna:'TNA sheet',plan:'Planning',file:'Production file',bom:'BOM'};
function pendingFor(u){const L=[];JOBS.forEach(j=>{if(!seeJob(j)&&!['cad','ie','plan','store'].includes(u.kind))return;const w=j.wf;const mine=u.kind==='m'?j.merch===u.name:u.kind==='t'?j.buyerName===u.team:false;
  if(mine){if(w.order==='review'&&j.demo)L.push([j,'order','Review the imported order and confirm']);if(j.demo&&w.order==='done'&&j.bomV!=='Ready')L.push([j,'bom','Prepare the trims & accessories checklist']);if(j.demo&&w.order==='done'&&j.labS&&j.labS.k==='none')L.push([j,'lab','Submit lab dips ('+j.colors.length+' colours)']);if(w.fabric==='ready'&&j.demo)L.push([j,'fabric','Prepare the fabric order sheet']);if(w.tna==='ready'&&j.demo)L.push([j,'tna','Fill and send the TNA sheet']);if(w.file==='ready')L.push([j,'file','Hand over the production file to the departments']);if(j.demo&&w.ppm==='ready')L.push([j,'ppm','Call the PP meeting']);if(j.demo&&j.bomV==='Ready'&&bomOf(j).lines.some(l=>l.ord.st!=='Ordered'))L.push([j,'trims','Order trims and accessories'])}
  if(u.kind==='cad'&&w.cad==='ready')L.push([j,'cad','Enter fabric consumption']);
  if(u.kind==='ie'){if(w.ie==='ready')L.push([j,'ie','Prepare the IE bulletin']);if(w.thread==='ready')L.push([j,'thread','Give thread consumption'])}
  if(u.kind==='plan'){if(w.fabric==='sent')L.push([j,'plan','Approve the fabric order sheet']);if(w.tna==='sent')L.push([j,'plan','Generate the TNA and approve it']);if(j.demo&&w.order==='done'&&!j.itemDesc)L.push([j,'plan','Write the item and print/emb description']);if(j.demo&&w.preprod==='ready')L.push([j,'preprod','Follow up the pre-production work'])}
  if(u.kind==='tech'&&j.demo&&w.sizeset==='ready')L.push([j,'sizeset','Size set: mark OK when approved']);
  if(u.kind==='store'&&j.demo&&bomOf(j).lines.some(l=>l.ord.st==='Ordered'&&num(l.ord.recv)<num(l.ord.qty)))L.push([j,'trims','Update trims and accessories received'])});return L}
function renderRail(){const el=G('side');if(!el)return;const mob=mobile();overlay.classList.toggle('open',mob&&railOpen);
 const cur=selId&&JOBS.find(j=>j.id===selId);let mode=railMode;if((mode==='job'||mode==='form')&&!cur)mode='tasks';
 const pc=pendingFor(me).length;
 el.innerHTML=`<div class="rtabs"><button class="rtab ${mode==='tasks'?'on':''}" data-rm="tasks">My pending tasks<span class="rcnt">${pc}</span></button>${cur&&mode==='job'?'<button class="rtab on">Job detail</button>':''}${cur&&mode==='form'?`<button class="rtab on">${esc(FORMNAME[formType]||'Form')}</button>`:''}${mob?'<button class="rtab" data-rm="close" style="margin-left:auto">Close</button>':''}</div><div class="rpane" id="rpane"></div>`;
 el.querySelectorAll('[data-rm]').forEach(b=>b.onclick=()=>{const m=b.dataset.rm;if(m==='close'){closeRail();return}selId=null;formType='';REVIEW=null;railMode=m;render()});
 const p=G('rpane');if(mode==='tasks')tasksPane(p);else if(mode==='job')jobPane(p,cur);else formPane(p,cur)}
function goTask(id,k){if(k==='trims'){VIEW='trims';TRIMJOB=id;railMode='tasks';selId=null;render();return}if(k==='lab'){VIEW='follow';openRail('job',id);return}if(k==='trims'){VIEW='trims';railMode='tasks';selId=null;render();return}if(k==='bom'){VIEW='bom';openRail('form',id,'bom');return}VIEW='follow';openRail('form',id,k)}
function tasksPane(el){const L=pendingFor(me);
 el.innerHTML=`<div class="body"><div class="phint" style="margin-bottom:8px">${me.kind==='h'?'View only. Pending work of every department is in the cards above the table.':'Work waiting for you. Click one to open it.'}</div>${L.slice(0,40).map(([j,k,t])=>`<div class="tnaitem" data-t="${esc(j.id)}|${k}"><div><b>${esc(j.jobCode)}</b> · ${esc(j.style)}</div><div class="muted" style="font-size:12.5px">${esc(t)} · ${esc(j.merch)} · ${n(j.qty)} pcs</div></div>`).join('')||'<div class="empty">Nothing is waiting for you.</div>'}${L.length>40?`<div class="muted" style="font-size:12.5px">…and ${L.length-40} more. Use the cards above the table to filter them.</div>`:''}</div>`;
 el.querySelectorAll('[data-t]').forEach(x=>x.onclick=()=>{const [id,k]=x.dataset.t.split('|');goTask(id,k)})}
// ---------- job detail ----------
function readImg(file,cb){const fr=new FileReader();fr.onload=()=>{const im=new Image();im.onload=()=>{const c=document.createElement('canvas');const s=Math.min(1,240/Math.max(im.width,im.height));c.width=Math.max(1,Math.round(im.width*s));c.height=Math.max(1,Math.round(im.height*s));c.getContext('2d').drawImage(im,0,0,c.width,c.height);cb(c.toDataURL('image/jpeg',.72))};im.onerror=()=>toast('Could not read that image');im.src=fr.result};fr.readAsDataURL(file)}
function stepAction(j,k){const w=j.wf;const role={order:['m','t'],cad:['cad'],ie:['ie'],thread:['ie'],fabric:['m','t'],tna:['m','t'],file:['m','t'],preprod:['plan'],sizeset:['tech'],ppm:['m','t']}[k];
 if(!j.demo&&k!=='file')return null;
 const active=k==='order'?w.order==='review':(w[k]==='ready');const planWork=(k==='fabric'||k==='tna')&&w[k]==='sent';
 if(!active&&!planWork&&!(j.demo&&w[k]==='done'))return null;
 const mine=active&&role.includes(me.kind)&&((me.kind==='m')?j.merch===me.name:true);const pm=planWork&&me.kind==='plan';
 const label={order:'Review and confirm',cad:'Enter consumption',ie:'Prepare bulletin',thread:'Give thread consumption',fabric:'Prepare sheet',tna:'Fill and send',file:'Hand over',preprod:'Update areas',sizeset:'Mark size set OK',ppm:'Call the meeting'}[k];
 return {me:mine||pm,label:pm?'Approve':label,plan:planWork}}
function jobPane(el,j){const ed=canEdit(j);const w=j.wf;
 el.innerHTML=`<header><div><div class="muted" style="font-size:12.5px">${esc(j.buyerName)}${j.brand&&j.brand!==j.buyerName?' · '+esc(j.brand):''} · ${esc(j.merch)}</div><h3>${esc(j.jobCode)} · ${esc(j.style)}</h3><div style="margin-top:4px">${chip(j.stage,j.stage==='In production'?'good':'warn')}</div></div><button class="btn sm" id="jBack">Back</button></header>
 <div class="body"><div style="display:flex;gap:12px;align-items:flex-start;margin-bottom:8px"><div>${j.img?`<img src="${esc(j.img)}" alt="" style="width:110px;height:110px;object-fit:cover;border-radius:10px;display:block">`:'<div style="width:110px;height:110px;border-radius:10px;background:var(--chip);display:flex;align-items:center;justify-content:center;font-size:12px;color:var(--ink-2);text-align:center;padding:6px">No item image yet</div>'}${ed?`<label class="btn sm" style="display:block;margin-top:6px;text-align:center;cursor:pointer">${j.img?'Change image':'Upload image'}<input type="file" accept="image/*" id="jImg" style="display:none"></label>`:''}</div>
 <div class="kv" style="flex:1"><div><span>Order qty</span>${n(j.qty)} pcs</div><div><span>Style name</span>${esc(j.styleName||'—')}</div><div><span>Print / Emb</span>${esc(j.pe||'—')}</div><div><span>PP sample</span>${esc(j.pp||'—')}</div><div style="grid-column:1/-1"><span>Item description</span>${esc(j.itemDesc||'—')}</div><div style="grid-column:1/-1"><span>Print &amp; Emb description</span>${esc(j.peDesc||'—')}</div></div></div>
 <div class="kv"><div><span>File handover</span>${fmt(j.tFile||j.handover)}</div><div><span>Sewing start</span>${fmt(j.tSewS||j.sewTA)}</div><div><span>Cargo closing</span>${fmt(j.cargo)}</div><div><span>Fabric req. (grey / finish)</span>${j.greyKg==null?'—':n(j.greyKg)+' / '+n(j.finKg)+' kg'}</div>${j.country?`<div><span>Country (OVS)</span>${esc(j.country)}</div>`:''}</div>
${j.pos&&j.pos.length?`<div class="secttl">${j.pos.some(p=>p.type==='MARKET')?'Market-wise':'PO-wise'} quantity and delivery</div><table class="btab"><thead><tr><th>${j.pos.some(p=>p.type==='MARKET')?'Market':'PO'}</th><th class="num">Qty</th><th>CCD / ship</th><th>Cancel</th><th>Destination</th></tr></thead><tbody>${j.pos.map(p=>`<tr><td>${esc(p.po)}</td><td class="num">${n(p.qty)}</td><td>${fmt(p.ccd)}</td><td>${fmt(p.cancel)}</td><td>${esc(p.dest||'')}</td></tr>`).join('')}</tbody></table>`:''}
 ${j.meta&&Object.keys(j.meta).length?`<details class="who2" style="margin-top:8px"><summary>Everything found in the PO (${flat(j.meta).length} fields)</summary><div class="kv" style="margin-top:8px">${flat(j.meta).map(([k,v])=>`<div><span>${esc(k)}</span>${esc(v)}</div>`).join('')}</div></details>`:''}
 <div class="secttl">Workflow</div>${STEPS.map(([k,l,who])=>{const act=stepAction(j,k);return `<div class="wfrow"><span>${l}<div class="muted" style="font-size:11.5px">${who}</div></span>${stepPill(j,k)}<span>${act?`<button class="btn sm ${act.me?'primary':''}" data-act="${k}">${act.me?act.label:'Open'}</button>`:''}</span></div>`}).join('')}
 <div class="wfrow"><span>Cost sheet</span>${pill(j.csStatus==='Done'?'done':csOf(j)?'run':'none',j.csStatus==='Done'?'Done':csOf(j)?'Draft':'Not started')}<span><button class="btn sm" data-act="cost">Open</button></span></div>
 ${j.demo?`<div class="wfrow"><span>Trims checklist<div class="muted" style="font-size:11.5px">Merchandiser</div></span>${pill({Ready:'done',Draft:'run','Not started':'wait'}[j.bomV],j.bomV)}<span><button class="btn sm" data-act="bom">Open</button></span></div>`:''}
 ${lotHTML(j,ed)}
 ${j.demo&&j.colors?`<div class="secttl">Colour × size and lab dip</div><div style="overflow-x:auto"><table class="btab"><thead><tr><th>Colour</th>${j.sizes.map(s=>`<th class="num">${esc(s)}</th>`).join('')}<th class="num">Total</th><th>Lab dip</th><th class="num">Times</th></tr></thead><tbody>${j.colors.map(c=>{const t=c.qty.reduce((a,b)=>a+b,0);const l=j.lab[c.name]||{s:'Not started',r:0};return `<tr><td>${esc(c.name)}</td>${c.qty.map(x=>`<td class="num">${x}</td>`).join('')}<td class="num"><b>${n(t)}</b></td><td>${ed?`<select class="inl ${LABST[l.s]}" data-lab="${esc(c.name)}">${LAB.map(x=>`<option ${x===l.s?'selected':''}>${x}</option>`).join('')}</select>`:pill(LABST[l.s],l.s)}</td><td class="num">${l.r}</td></tr>`}).join('')}</tbody></table></div>`:''}
 <div class="secttl">History</div><div class="tl">${(j.hist||[]).slice().reverse().slice(0,12).map(e=>`<div><b>${fmt(e[0])}</b> · <span class="muted">${esc(e[1])}</span> · ${esc(e[2])}</div>`).join('')||'<span class="muted">No changes yet.</span>'}</div></div>`;
 G('jBack').onclick=()=>{selId=null;railMode='tasks';render()};
 el.querySelectorAll('[data-act]').forEach(b=>b.onclick=()=>{const k=b.dataset.act;if(k==='cost'){VIEW='print';PRINTJOB=j.id;COSTOPEN=true;selId=null;railOpen=false;render();window.scrollTo(0,0);return}if(k==='bom'){VIEW='bom';openRail('form',j.id,'bom');return}openRail('form',j.id,(k==='fabric'||k==='tna')&&me.kind==='plan'?'plan':k)});
 const im=G('jImg');if(im)im.onchange=()=>{if(im.files&&im.files[0])readImg(im.files[0],d=>{j.img=d;if(!j.demo)own(j.id).img=d;histAdd(j,'Item image uploaded');save();toast('Item image saved');render()})};
 el.querySelectorAll('[data-lab]').forEach(s=>s.onchange=()=>{const c=s.dataset.lab;const l=j.lab[c]||(j.lab[c]={s:'Not started',r:0});const old=l.s;l.s=s.value;if(s.value==='Submitted')l.r=(l.r||0)+1;histAdd(j,`Lab dip ${c}: ${old} → ${s.value}`);save();toast(`Lab dip updated: ${c}`);render()});bindLot(el,j,ed)}
// ---------- order entry: AI entry (PO import with the ERP's own buyer parsers) and manual entry ----------
const PARTS=['Body','Sleeve','Neck rib','Cuff & bottom rib','Neck tape','Collar','Cuff','Placket','Pocket','Hood','Hood lining','Waistband','Contrast panel'];
const FABRICS=['Single Jersey','Single Jersey Lycra','Slub Jersey','Pique','Lacoste','Interlock','Rib 1x1','Rib 2x2','Rib 1x2','Rib 4x4','Rib 2x1 Lycra','Fleece 3-thread','Fleece brushed','French Terry (loop back)','Waffle','Pointelle','Drop needle','Jacquard','Mesh','Velour','Thermal'];
const COMPS=['100% Cotton','100% Organic Cotton','95% Cotton 5% Elastane','95% Organic Cotton 5% Elastane','90% Cotton 10% Polyester','80% Cotton 20% Polyester','60% Cotton 40% Polyester','50% Cotton 50% Polyester','65% Polyester 35% Cotton','100% Polyester','100% Recycled Polyester','95% Viscose 5% Elastane','100% Viscose'];
const BUYERS=['NAME IT','ONLY','ONLY & SONS','OVS','UTG','New Look','T.M. Lewin','Maurices'];
const ORD=n=>{n=Math.floor(num(n));const v=n%100;return n+((v>=11&&v<=13)?'th':({1:'st',2:'nd',3:'rd'}[n%10]||'th'))};
const sumQ=a=>a.reduce((x,y)=>x+num(y),0);
function aggregate(pos){const sizes=[];pos.forEach(p=>{const g=p.grid||p;(g.sizes||[]).forEach(s=>{if(!sizes.includes(s))sizes.push(s)})});const map=new Map();
 pos.forEach(p=>{const g=p.grid||p;(g.colors||[]).forEach(c=>{const k=c.name+'|'+(c.code||'');let t=map.get(k);if(!t){t={name:c.name,code:c.code||'',qty:sizes.map(()=>0)};map.set(k,t)}(g.sizes||[]).forEach((s,si)=>{t.qty[sizes.indexOf(s)]+=num(c.qty[si])})})});
 return{sizes,colors:[...map.values()]}}
function flat(o){const out=[];Object.entries(o||{}).forEach(([k,v])=>{if(v==null||v==='')return;out.push([k.replace(/([A-Z])/g,' $1').replace(/^./,c=>c.toUpperCase()),typeof v==='object'?JSON.stringify(v):String(v)])});return out}
// ---- job numbers: same rule as the ERP (one running sequence; repeat = base job + lot) ----
const SHORT=b=>BCODE(b);
const baseOf=s=>{const m=String(s||'').match(/\d{4,}/);return m?m[0]:''};
const lotOf=s=>{const m=String(s||'').match(/\b(\d+)(st|nd|rd|th)\b/i);return m?+m[1]:1};
const SEQKEY='nos-jobseq-v1';
function seqLast(){try{const v=localStorage.getItem(SEQKEY);if(v)return +v}catch(e){}return Math.max(48907,...JOBS.map(j=>+baseOf(j.job)||0))}
function setSeq(v){try{localStorage.setItem(SEQKEY,String(v))}catch(e){}}
function nextLot(base){let mx=0;JOBS.forEach(j=>{if(baseOf(j.job)===base)mx=Math.max(mx,lotOf(j.job))});return mx+1}
function jobNoFor(R){if(R.jobType==='REPEAT'){const b=baseOf(R.base);return b?`${b} ${ORD(R.lot||nextLot(b))}`:''}return R._edit?R.job:String(seqLast()+1)}
const jobShow=R=>{const x=jobNoFor(R);return x?BCODE(R.buyer)+' '+x:''};
// ---- review model: per style one size list + one colour list; every PO has its own colour × size quantities ----
function emptyQ(S){return S.colors.map(()=>S.sizes.map(()=>0))}
function newPO(S,prev){return{ref:'',type:prev?prev.type:'PO',declared:0,ccd:prev?prev.ccd:addDays(TODAY,90),cancel:prev?prev.cancel:'',dest:prev?prev.dest:'',market:'',meta:{},q:emptyQ(S)}}
function buyerGuess(R){if(R.buyerPick)return R.buyerPick;if(/^OVS/.test(R.parser))return'OVS';if(/^UTG/.test(R.parser))return'UTG';const d=String((R.styles[0]||{}).desc||'').toUpperCase();if(/^ONS/.test(d))return'ONLY & SONS';if(/^(NM|NB|NAME)/.test(d))return'NAME IT';return'ONLY'}
function baseR(o){return Object.assign({source:'Manual entry',parser:'Manual',warnings:[],sha:'',buyerPick:'',buyer:me.team&&BUYERS.includes(me.team)?me.team:'NAME IT',brand:'',jobType:'NEW',base:'',lot:'',poRcvd:TODAY,pe:'None',img:'',approve:false,si:0,coll:'',merch:''},o)}
function previewToR(pv,buyerPick){const R=baseR({source:pv.sourceFileName,parser:pv.parserFamily+' '+pv.parserVersion,warnings:(pv.warnings||[]).slice(),sha:(pv.sourceMetadata||{}).fileSha256||'',buyerPick:buyerPick||'',styles:[]});
 pv.styles.forEach(st=>{const refs=(st.orderReferences&&st.orderReferences.length)?st.orderReferences:[{reference:'',referenceType:'PO',totalQty:st.totalQty,colors:st.colors}];
  const sizes=[],colors=[];refs.forEach(r=>r.colors.forEach(c=>{c.sizes.forEach(s=>{if(!sizes.includes(s.size))sizes.push(s.size)});if(!colors.find(x=>x.name===c.color&&x.code===(c.colorCode||'')))colors.push({name:c.color,code:c.colorCode||''})}));
  const S={styleNo:st.styleNo,desc:st.styleDescription||'',item:'',collection:st.collection||'',season:st.season||'',sizes,colors,open:0,parts:[],pos:[]};
  const m=st.metadata||{};const rm=(refs[0]&&refs[0].metadata)||{};S.meta=Object.assign({},m,{orderType:rm.orderType,pricePerItem:m.pricePerItem||rm.pricePerItem,currency:m.currency||rm.currency});S.collection=S.collection||rm.collection||'';
  S.fob=m.pricePerItem||rm.pricePerItem||'';S.parts=[{part:'Body',gsm:'',fabric:'',comp:m.fabricComposition||rm.fabricComposition||m.descriptionComposition||''}];
  S.pos=refs.map(r=>({ref:r.reference||'',type:r.referenceType||'PO',declared:r.totalQty,ccd:r.ccd||r.shipmentDate||'',cancel:r.cancelDate||'',dest:r.destination||r.market||'',market:r.market||'',meta:r.metadata||{},
   q:colors.map(c=>{const f=r.colors.find(x=>x.color===c.name&&(x.colorCode||'')===c.code);return sizes.map(sz=>{const s=f&&f.sizes.find(y=>y.size===sz);return s?s.qty:0})}),
   ean:r.colors.reduce((m2,c)=>{c.sizes.forEach(s=>{if(s.ean)m2[c.color+'|'+s.size]=s.ean});return m2},{})}));
  R.styles.push(S)});
 R.buyer=buyerGuess(R);R.coll=(R.styles[0]&&R.styles[0].collection)||'';return R}
function manualR(){const S={fob:'',styleNo:'',desc:'',item:'',collection:'',season:'',meta:{},open:0,parts:[{part:'Body',gsm:'',fabric:'',comp:''}],sizes:SIZESETS.adult.slice(),colors:[{name:'',code:''}],pos:[]};S.pos=[newPO(S)];return baseR({styles:[S]})}
function jobToR(j){const S={fob:j.fob||'',styleNo:j.style,desc:j.styleName||'',item:j.item||'',collection:j.coll||'',season:j.season||'',meta:j.meta||{},open:0,parts:j.parts.map(p=>({part:p.part,gsm:p.gsm,fabric:p.fabric||'',comp:p.comp})),sizes:j.sizes.slice(),colors:j.colors.map(c=>({name:c.name,code:c.code||''})),pos:[]};
 S.pos=j.pos.map(p=>{const g=p.grid||(j.pos.length===1?{sizes:j.sizes,colors:j.colors}:{sizes:j.sizes,colors:[]});return{ref:p.po||'',type:p.type||'PO',declared:p.qty,ccd:p.ccd||'',cancel:p.cancel||'',dest:p.dest||'',market:p.market||'',meta:p.meta||{},
  q:S.colors.map(c=>{const f=g.colors.find(x=>x.name===c.name);return S.sizes.map(sz=>{const i=g.sizes.indexOf(sz);return f&&i>=0?num(f.qty[i]):0})}),ean:{}}});
 return baseR({_edit:j.id,job:j.job,source:j.source||'',parser:j.parser||'Manual',warnings:j.warnings||[],sha:j.srcSha||'',buyerPick:j.buyerName,buyer:j.buyerName,brand:j.brand||'',poRcvd:j.poRcvd||TODAY,pe:j.pe||'None',img:j.img||'',coll:j.coll||'',merch:j.merch,styles:[S]})}
const poQty=P=>P.q.reduce((a,r)=>a+sumQ(r),0);
function styleTotals(S){return S.colors.map((c,ci)=>S.sizes.map((s,si)=>S.pos.reduce((a,P)=>a+num((P.q[ci]||[])[si]),0)))}
function rStylesForCheck(R){return R.styles.map(S=>{const toC=q=>S.colors.map((c,ci)=>({color:c.name,colorCode:c.code,totalQty:sumQ(q[ci]||[]),sizes:S.sizes.map((s,si)=>({size:s,qty:num((q[ci]||[])[si])}))})).filter(c=>c.totalQty>0);
 const refs=S.pos.map(P=>({reference:P.ref||'(missing)',referenceType:P.type,totalQty:poQty(P),colors:toC(P.q)}));
 return{styleNo:S.styleNo||'(no style)',totalQty:refs.reduce((a,r)=>a+r.totalQty,0),colors:toC(styleTotals(S)),orderReferences:refs}})}
const LADDERS=[['3XS','XXS','XS','S','M','L','XL','XXL','3XL','4XL','5XL'],['44','50','56','62','68','74','80','86','92','98','104','110','116','122','128','134','140','146','152','158','164','170','176'],['1Y','2Y','3Y','4Y','5Y','6Y','7Y','8Y','9Y','10Y','11Y','12Y','13Y','14Y','15Y','16Y'],['0-1M','1-3M','3-6M','6-9M','9-12M','12-18M','18-24M']];
const SZALIAS={'2XL':'XXL','XXXL':'3XL','2XS':'XXS'};
function nextSize(list,dir){const edge=String(dir==='lo'?list[0]:list[list.length-1]||'').toUpperCase();const e=SZALIAS[edge]||edge;for(const L of LADDERS){const i=L.indexOf(e);if(i>=0){const k=dir==='lo'?i-1:i+1;const z=L[k];return z&&!list.includes(z)?z:null}}return null}
function setSizes(S,list){const old=S.sizes;S.sizes=list;S.pos.forEach(P=>{P.q=S.colors.map((c,ci)=>list.map(sz=>{const i=old.indexOf(sz);return i>=0?num((P.q[ci]||[])[i]):0}))})}
// ---- reading files ----
async function sha256(buf){try{const h=await crypto.subtle.digest('SHA-256',buf);return [...new Uint8Array(h)].map(b=>b.toString(16).padStart(2,'0')).join('')}catch(e){let h=0;const u=new Uint8Array(buf);for(let i=0;i<u.length;i++)h=(h*31+u[i])|0;return 'weak-'+u.length+'-'+h}}
async function pdfLayoutText(buf){const lib=window.pdfjsLib;if(!lib)throw new Error('The PDF reader could not be loaded. Check the internet connection and try again.');
 try{if(lib.GlobalWorkerOptions&&!lib.GlobalWorkerOptions.workerSrc)lib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js'}catch(e){}
 const pdf=await lib.getDocument({data:new Uint8Array(buf)}).promise;let out='';
 for(let p=1;p<=pdf.numPages;p++){const page=await pdf.getPage(p);const c=await page.getTextContent({normalizeWhitespace:false,disableCombineTextItems:false});
  const items=c.items.map(i=>({text:String(i.str||'').trim(),x:Number(i.transform[4]||0),y:Number(i.transform[5]||0)})).filter(i=>i.text);
  items.sort((a,b)=>{const dy=b.y-a.y;return Math.abs(dy)>2?dy:a.x-b.x});const lines=[];
  for(const it of items){const l=lines[lines.length-1];if(!l||Math.abs(l.y-it.y)>2)lines.push({y:it.y,items:[{text:it.text,x:it.x}]});else l.items.push({text:it.text,x:it.x})}
  out+=(p>1?'\n\f\n':'')+lines.map(l=>l.items.sort((a,b)=>a.x-b.x).map(x=>x.text).join(' ')).join('\n')}
 if(!out.trim())throw new Error('No embedded text found. Scanned or image-only PDFs need OCR first.');return out}
async function readPoFile(file,buyerCode){const buf=await file.arrayBuffer();const sha=await sha256(buf);let pv;
 if(/\.(xlsx|xls|csv)$/i.test(file.name)){if(!window.XLSX)throw new Error('The Excel reader could not be loaded. Check the internet connection and try again.');pv=window.NOSImport.parseExcel(new Uint8Array(buf),file.name,buyerCode)}
 else pv=window.NOSImport.parseText(await pdfLayoutText(buf),file.name,buyerCode);
 pv.sourceMetadata=Object.assign({},pv.sourceMetadata,{fileSha256:sha});return pv}
let ENTRY_MODE='ai',ENTRY_MSG='',LAST=null;
const XKEY='nos-xtasks-v1';const xget=()=>{try{return JSON.parse(localStorage.getItem(XKEY)||'[]')}catch(e){return[]}};const xset=a=>{try{localStorage.setItem(XKEY,JSON.stringify(a))}catch(e){}};
function seqCard(){if(me.kind!=='admin')return '';const last=seqLast();return `<div class="panel pad"><div class="ptitle">Job numbering</div><div class="form" style="grid-template-columns:minmax(160px,240px) auto;align-items:end"><label>Last job no. used<input type="number" id="seqIn" value="${last}"></label><div><button class="btn primary" id="seqSave">Save</button></div></div><div class="muted" style="font-size:12.5px;margin-top:6px">Next new job: <b>${last+1}</b> (shown as BS-ONL ${last+1}, BS-NMT, BS-ONS, OVS, UT)</div></div>`}
function lastCard(){if(!LAST)return '';return `<div class="panel pad okcard" style="margin-top:12px"><div style="display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap;align-items:center"><div><b>${esc(LAST.job)} created</b> · ${n(LAST.qty)} pcs · ${LAST.styles} style(s) · ${LAST.pos} PO(s)</div><button class="btn sm" id="lastOpen">Open job</button></div>
 <div class="tasksent">${LAST.tasks.map(t=>`<div><span class="dept">${esc(t[0])}</span>${esc(t[1])}</div>`).join('')}</div></div>`}
function entryView(m){const waiting=JOBS.filter(j=>j.demo&&j.wf.order==='review'&&seeJob(j));
 m.innerHTML=roleBar()+seqCard()+lastCard()+(canNew()?`<div class="panel pad" style="margin-top:12px"><div class="entrybar"><div class="subtabs" role="tablist"><button class="${ENTRY_MODE==='ai'?'on':''}" data-em="ai">Import PO</button><button class="${ENTRY_MODE==='manual'?'on':''}" data-em="manual">Manual entry</button></div>
  ${ENTRY_MODE==='ai'?`<select id="aiBuyer" aria-label="Buyer"><option value="">Buyer: auto-detect</option>${['ONLY','NAME IT','ONLY & SONS','OVS','UTG'].map(b=>`<option>${b}</option>`).join('')}</select><label class="btn primary filebtn">Choose PO file<input type="file" id="aiFile" accept=".pdf,.xlsx,.xls,.csv"></label>`:''}</div>
  ${ENTRY_MSG?`<div id="aiMsg" class="${ENTRY_MSG.startsWith('!')?'warn-line':'muted'}" style="margin-top:8px;font-size:13px">${esc(ENTRY_MSG.replace(/^!/,''))}</div>`:'<div id="aiMsg"></div>'}</div>
  <section class="panel" id="reviewHost" style="margin-top:12px;display:${REVIEW?'block':'none'}"></section>`:'')+
 (waiting.length?`<div class="panel pad" style="margin-top:12px"><div class="ptitle">Waiting for review (${waiting.length})</div><table class="btab"><thead><tr><th>Job</th><th>Style</th><th>Buyer</th><th class="num">Qty</th><th></th></tr></thead><tbody>${waiting.map(j=>`<tr><td><b>${esc(j.job)}</b></td><td>${esc(j.style)}</td><td>${esc(j.buyerName)}</td><td class="num">${n(j.qty)}</td><td><button class="btn sm primary" data-rev="${esc(j.id)}">Review</button></td></tr>`).join('')}</tbody></table></div>`:'');
 bindBar();
 const ss=G('seqSave');if(ss)ss.onclick=()=>{const v=Math.floor(num(G('seqIn').value));if(v<1){toast('Enter a job number');return}setSeq(v);toast(`Last job no. set to ${v}. Next new job is ${v+1}.`);render()};
 const lo=G('lastOpen');if(lo)lo.onclick=()=>{const id=LAST.id;LAST=null;VIEW='follow';openRail('job',id)};
 m.querySelectorAll('[data-em]').forEach(b=>b.onclick=()=>{ENTRY_MODE=b.dataset.em;ENTRY_MSG='';LAST=null;REVIEW=ENTRY_MODE==='manual'?manualR():null;render()});
 const af=G('aiFile');if(af)af.onchange=async()=>{const f=af.files&&af.files[0];if(!f)return;LAST=null;ENTRY_MSG='Reading '+f.name+' …';G('aiMsg').className='muted';G('aiMsg').textContent=ENTRY_MSG;
  try{const buyer=G('aiBuyer').value;const pv=await readPoFile(f,buyer||undefined);REVIEW=previewToR(pv,buyer);ENTRY_MSG=`${f.name} · ${pv.styles.length} style(s) · ${pv.styles.reduce((a,s)=>a+(s.orderReferences||[]).length,0)} PO / market(s)`}catch(e){REVIEW=null;ENTRY_MSG='!'+(e&&e.message?e.message:'The file could not be read')}render()};
 m.querySelectorAll('[data-rev]').forEach(b=>b.onclick=()=>{const j=JOBS.find(x=>x.id===b.dataset.rev);REVIEW=jobToR(j);render()});
 if(REVIEW&&G('reviewHost'))reviewForm(G('reviewHost'),REVIEW)}
