  hv('rBuyer',v=>{R.buyer=v;R.buyerPick=v});hv('rBrand',v=>R.brand=v);hv('rRcvd',v=>R.poRcvd=v);hv('rPE',v=>R.pe=v);hv('rMerch',v=>R.merch=v);hv('rLot',v=>R.lot=v);
  const bs=$('rBase');if(bs){bs.oninput=()=>{R.base=bs.value;refresh()};bs.onchange=()=>{R.base=bs.value;R.lot='';draw()}}
