  el.querySelectorAll('[data-copy]').forEach(b=>b.onclick=()=>{const pi=+b.dataset.copy;S.pos[pi].q=S.pos[pi-1].q.map(r=>r.slice());draw()});
  el.querySelectorAll('[data-clear]').forEach(b=>b.onclick=()=>{const pi=+b.dataset.clear;S.pos[pi].q=emptyQ(S);draw()});
