 bindBar();m.querySelectorAll('[data-bf]').forEach(b=>b.onclick=()=>{F.bom=F.bom===b.dataset.bf?'':b.dataset.bf;render()});
 m.querySelectorAll('[data-bj]').forEach(tr=>tr.onclick=()=>{openRail('form',tr.dataset.bj,'bom')});
