function bomForm(el,j,ed,head,lock,back){const $=G;const b=j.bom;const lines=b.lines;
 el.innerHTML=`${head('Trims & accessories checklist',n(j.qty)+' pcs')}<div class="body">${lock}<div class="muted" style="font-size:12.5px;margin-bottom:6px">${pill({Ready:'done',Draft:'run','Not started':'wait'}[j.bomV],j.bomV)}</div>
 <div style="overflow-x:auto"><table class="colorrows" id="bTbl"><thead><tr><th>Item</th><th>Specification</th><th style="width:64px">Unit</th><th style="width:74px">Per pc</th><th style="width:64px">Waste %</th><th class="num" style="width:86px">Needed</th><th style="width:30px"></th></tr></thead><tbody>${lines.map((l,i)=>`<tr data-i="${i}"><td><input data-f="name" value="${esc(l.name)}" ${ed?'':'disabled'}></td><td><input data-f="spec" value="${esc(l.spec)}" ${ed?'':'disabled'}></td><td><select data-f="unit" ${ed?'':'disabled'}>${['pcs','m','cone','kg','set'].map(u=>`<option ${u===l.unit?'selected':''}>${u}</option>`).join('')}</select></td><td><input type="number" step="any" data-f="per" value="${esc(l.per)}" ${ed?'':'disabled'}></td><td><input type="number" step="any" data-f="waste" value="${esc(l.waste)}" ${ed?'':'disabled'}></td><td class="num" id="bn${i}">${n(Math.ceil(lineNeed(j,l)))}</td><td>${ed&&l.ord.st!=='Ordered'?`<button class="btn sm" data-rm="${i}" aria-label="Remove">✕</button>`:''}</td></tr>`).join('')}</tbody></table></div>
 ${ed?'<div style="margin-top:6px;display:flex;gap:8px;flex-wrap:wrap"><button class="btn sm" id="bAdd">Add line</button><button class="btn sm" id="bStd">Add the standard list for this item</button></div>':''}</div>
 <div class="foot"><button class="btn" id="bPrint">Print</button>${ed?`<button class="btn" id="bSave">Save draft</button><button class="btn primary" id="bReady">Mark ready</button>`:''}</div>`;back();
 $('bPrint').onclick=()=>{if(ed)read();printSheet(bomSheetHTML(j))};
 const read=()=>{el.querySelectorAll('#bTbl tbody tr').forEach(tr=>{const l=lines[+tr.dataset.i];tr.querySelectorAll('[data-f]').forEach(i=>{const f=i.dataset.f;l[f]=(f==='per'||f==='waste')?num(i.value):i.value})})};
 el.querySelectorAll('#bTbl [data-f]').forEach(i=>i.oninput=i.onchange=()=>{read();el.querySelectorAll('#bTbl tbody tr').forEach(tr=>{const c=$('bn'+tr.dataset.i);if(c)c.textContent=n(Math.ceil(lineNeed(j,lines[+tr.dataset.i])))})});
 el.querySelectorAll('[data-rm]').forEach(b=>b.onclick=()=>{read();lines.splice(+b.dataset.rm,1);bomForm(el,j,ed,head,lock,back)});
 if($('bAdd'))$('bAdd').onclick=()=>{read();lines.push(mkLine('','','pcs',1,3));bomForm(el,j,ed,head,lock,back)};
 if($('bStd'))$('bStd').onclick=()=>{read();const have=new Set(lines.map(l=>l.name));bomTemplate(j).forEach(l=>{if(!have.has(l.name))lines.push(l)});bomForm(el,j,ed,head,lock,back)};
 if($('bSave'))$('bSave').onclick=()=>{read();if(b.status==='Not started')b.status='Draft';histAdd(j,'Trims checklist draft saved');save();toast('Draft saved');render()};
 if($('bReady'))$('bReady').onclick=()=>{read();if(!lines.length||lines.some(l=>!l.name.trim())){toast('Fill the item name on every line');return}b.status='Ready';histAdd(j,`Trims checklist ready (${lines.length} items)`);save();toast(`Checklist ready for ${j.jobCode}`);render()}}
// ---------- trims & accessories ordering ----------
let TRIMJOB=null;
function ordState(j){const L=bomOf(j).lines;const o=L.filter(l=>l.ord.st==='Ordered');const need=o.reduce((a,l)=>a+num(l.ord.qty),0),rec=o.reduce((a,l)=>a+Math.min(num(l.ord.recv),num(l.ord.qty)),0);
 return{n:L.length,o:o.length,i:need===0?'Not received':rec>=need&&o.length===L.length?'All received':rec>0?'Partly received':'Not received'}}
function trimsView(m){const jobs=JOBS.filter(j=>seeJob(j)&&j.demo&&j.bomV==='Ready');const isStore=me.kind==='store';
 const cur=TRIMJOB&&jobs.find(j=>j.id===TRIMJOB);
 if(cur){const j=cur;const L=bomOf(j).lines;const s0=ordState(j);const ed=canEdit(j)&&!isStore;
  m.innerHTML=roleBar()+`<div class="panel pad"><div style="display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap;align-items:center"><div><button class="btn sm" id="tBack">← All jobs</button> <b style="margin-left:6px">${esc(j.jobCode)}</b> · ${esc(j.style)} · ${n(j.qty)} pcs</div><div class="ms"><button class="btn sm" id="tPrint">Print checklist</button>${ed&&s0.o<s0.n?'<button class="btn sm primary" id="tAll">Mark all ordered</button>':''}</div></div>
   <div class="ms" style="margin-top:8px">${chip(s0.n+' items')} ${chip('Ordered '+s0.o+' / '+s0.n,s0.o===s0.n?'good':'warn')} ${chip('In-house: '+s0.i,TRIMIST[s0.i]==='done'?'good':TRIMIST[s0.i]==='wait'?'warn':'bad')}</div></div>
   <div class="panel" style="margin-top:12px"><div class="tablewrap" style="min-height:0"><table class="noband"><thead><tr class="hdr"><th class="sk sk0">Item</th><th>Specification</th><th>Unit</th><th class="num">Required qty</th><th>Order status</th><th>Ordered on</th><th class="num">Received</th><th>In-house</th></tr></thead><tbody>${L.map((l,i)=>{const r=num(l.ord.recv),q=num(l.ord.qty)||Math.ceil(lineNeed(j,l));const st=l.ord.st!=='Ordered'?['none','—']:r>=q?['done','All received']:r>0?['wait','Partly received']:['late','Not received'];
    return `<tr data-li="${i}"><td class="sk sk0"><b>${esc(l.name)}</b></td><td>${esc(l.spec)}</td><td>${esc(l.unit)}</td><td class="num">${n(Math.ceil(lineNeed(j,l)))}</td><td><select class="inl ${l.ord.st==='Ordered'?'done':'wait'}" data-ost="${i}" ${ed?'':'disabled'}><option ${l.ord.st!=='Ordered'?'selected':''}>Not ordered</option><option ${l.ord.st==='Ordered'?'selected':''}>Ordered</option></select></td><td>${fmt(l.ord.date)}</td><td class="num">${isStore&&l.ord.st==='Ordered'?`<input type="number" style="width:84px" data-rcv="${i}" value="${r}">`:n(r)}</td><td>${pill(st[0],st[1])}</td></tr>`}).join('')}</tbody></table></div></div>`;
  bindBar();G('tBack').onclick=()=>{TRIMJOB=null;render()};G('tPrint').onclick=()=>printSheet(bomSheetHTML(j));
  const all=G('tAll');if(all)all.onclick=()=>{let c=0;L.forEach(l=>{if(l.ord.st!=='Ordered'){l.ord={st:'Ordered',qty:String(Math.ceil(lineNeed(j,l))),date:TODAY,recv:num(l.ord.recv)};c++}});histAdd(j,`All trims and accessories ordered (${c} items)`);save();toast(`${c} items marked ordered for ${j.jobCode}.`);render()};
  m.querySelectorAll('[data-ost]').forEach(x=>x.onchange=()=>{const l=L[+x.dataset.ost];if(x.value==='Ordered'){l.ord={st:'Ordered',qty:String(Math.ceil(lineNeed(j,l))),date:TODAY,recv:num(l.ord.recv)};histAdd(j,'Ordered: '+l.name)}else{l.ord={st:'Not ordered',qty:'',date:'',recv:0};histAdd(j,'Order cancelled: '+l.name)}save();render()});
  m.querySelectorAll('[data-rcv]').forEach(x=>x.onchange=()=>{const l=L[+x.dataset.rcv];l.ord.recv=Math.max(0,Math.floor(num(x.value)));histAdd(j,`Store received ${l.name}: ${n(l.ord.recv)}`);save();render()});
  return}
 const q=(F.q||'').toLowerCase();const S=j=>ordState(j);
 const rows=jobs.filter(j=>(!q||(j.jobCode+' '+j.style).toLowerCase().includes(q))&&(!F.tst||({'To order':S(j).o<S(j).n,'Ordered, not received':S(j).o===S(j).n&&S(j).i==='Not received','Partly received':S(j).i==='Partly received','All received':S(j).i==='All received'})[F.tst]));
 const c=f=>jobs.filter(f).length;
 m.innerHTML=roleBar()+`<div class="kpis" style="grid-template-columns:repeat(4,minmax(0,1fr))"><button class="kpi warn ${F.tst==='To order'?'on':''}" data-tf="To order"><div class="n">${c(j=>S(j).o<S(j).n)}</div><div class="l">To order</div></button><button class="kpi ${F.tst==='Ordered, not received'?'on':''}" data-tf="Ordered, not received"><div class="n">${c(j=>S(j).o===S(j).n&&S(j).i==='Not received')}</div><div class="l">Ordered, not in-house</div></button><button class="kpi warn ${F.tst==='Partly received'?'on':''}" data-tf="Partly received"><div class="n">${c(j=>S(j).i==='Partly received')}</div><div class="l">Partly in-house</div></button><button class="kpi good ${F.tst==='All received'?'on':''}" data-tf="All received"><div class="n">${c(j=>S(j).i==='All received')}</div><div class="l">All in-house</div></button></div>
 <div class="fbar"><input type="search" id="tq" placeholder="Search job or style" value="${esc(F.q)}" aria-label="Search"><button class="btn sm" id="tclear">Clear</button></div>
 <div class="panel"><div class="tablewrap" style="min-height:0"><table class="noband"><thead><tr class="hdr"><th class="sk sk0">Job</th><th>Style</th><th class="num">Qty</th><th class="num">Items</th><th>Ordered</th><th>In-house</th><th></th></tr></thead><tbody>${rows.map(j=>{const s1=S(j);return `<tr data-tjob="${esc(j.id)}"><td class="sk sk0"><b>${esc(j.jobCode)}</b></td><td>${esc(j.style)}</td><td class="num">${n(j.qty)}</td><td class="num">${s1.n}</td><td>${pill(s1.o===s1.n?'done':s1.o?'run':'wait',s1.o+' / '+s1.n)}</td><td>${pill(TRIMIST[s1.i],s1.i)}</td><td><button class="btn sm primary">Open</button></td></tr>`}).join('')}</tbody></table>${rows.length?'':'<div class="empty">No job</div>'}</div></div>`;
 bindBar();m.querySelectorAll('[data-tf]').forEach(b=>b.onclick=()=>{F.tst=F.tst===b.dataset.tf?'':b.dataset.tf;render()});
 const tq=G('tq');tq.oninput=()=>{F.q=tq.value;clearTimeout(trimsView.t);trimsView.t=setTimeout(()=>{render();const e=G('tq');e.focus();e.setSelectionRange(e.value.length,e.value.length)},280)};G('tclear').onclick=()=>{F.q='';F.tst='';render()};
 m.querySelectorAll('[data-tjob]').forEach(tr=>tr.onclick=()=>{TRIMJOB=tr.dataset.tjob;render();window.scrollTo(0,0)})}
// ---------- print: fabric order sheet, TNA, cost sheet, trims & accessories checklist ----------
let PRINTJOB=null,COSTOPEN=false,PRQ='';
const csOf=j=>j.demo?j.cs:(OWN[j.id]||{}).cs;
function printView(m){const cur=PRINTJOB&&JOBS.find(j=>j.id===PRINTJOB);
 if(cur&&COSTOPEN){const j=cur;m.innerHTML=roleBar()+'<section class="panel entry costpanel" id="costHost"></section>';bindBar();
  NOSCost.form(G('costHost'),csOf(j)||NOSCost.defaults({qty:j.qty}),{ed:canEdit(j),head:{buyer:j.buyerName,sub:j.brand||'',style:j.style,coll:j.coll||'',garment:j.itemDesc||j.styleName||j.item||'',date:TODAY,qty:j.qty},print:printSheet,toast,
   onBack:()=>{COSTOPEN=false;render()},
   onSave:(v,r,submit)=>{if(j.demo)j.cs=v;else own(j.id).cs=v;j.csStatus=submit?'Done':'Draft';if(!j.demo)own(j.id).csStatus=j.csStatus;histAdd(j,submit?'Cost sheet submitted, FOB $'+NOSCost.f2(r.fob):'Cost sheet draft saved');save();toast(submit?`Cost sheet saved. FOB $${NOSCost.f2(r.fob)}`:'Draft saved');COSTOPEN=false;render()}});return}
 const q=PRQ.toLowerCase();const list=JOBS.filter(j=>seeJob(j)&&(!q||(j.jobCode+' '+j.style).toLowerCase().includes(q))).sort((a,b)=>(b.demo?1:0)-(a.demo?1:0)).slice(0,40);
 const can=j=>({fab:j.demo&&j.wf.order==='done',tna:j.demo&&j.wf.order==='done',chk:j.demo&&bomOf(j).lines.length>0});
 m.innerHTML=roleBar()+`<div class="fbar"><input type="search" id="prq" placeholder="Search job or style" value="${esc(PRQ)}" aria-label="Search job or style"></div>
 ${cur?(()=>{const c=can(cur);return `<div class="panel pad" style="margin-bottom:12px"><div style="margin-bottom:8px"><b>${esc(cur.jobCode)}</b> · ${esc(cur.style)} · ${n(cur.qty)} pcs</div><div class="ms"><button class="btn primary" id="prFab" ${c.fab?'':'disabled'}>Fabric order sheet</button><button class="btn primary" id="prTna" ${c.tna?'':'disabled'}>TNA</button><button class="btn primary" id="prCost">Cost sheet</button><button class="btn primary" id="prChk" ${c.chk?'':'disabled'}>Trims &amp; accessories checklist</button></div></div>`})():''}
 <div class="panel"><div class="tablewrap" style="min-height:0"><table class="noband"><thead><tr class="hdr"><th class="sk sk0">Job</th><th>Style</th><th>Buyer</th><th class="num">Qty</th><th>Shipment</th></tr></thead><tbody>${list.map(j=>`<tr data-prj="${esc(j.id)}" class="${j.id===PRINTJOB?'sel':''}"><td class="sk sk0"><b>${esc(j.jobCode)}</b></td><td>${esc(j.style)}</td><td>${esc(j.buyerName)}</td><td class="num">${n(j.qty)}</td><td>${fmt(j.cargo)}</td></tr>`).join('')}</tbody></table>${list.length?'':'<div class="empty">No job found</div>'}</div></div>`;
 bindBar();const pq=G('prq');pq.oninput=()=>{PRQ=pq.value;clearTimeout(printView.t);printView.t=setTimeout(()=>{render();const e=G('prq');e.focus();e.setSelectionRange(e.value.length,e.value.length)},280)};
 m.querySelectorAll('[data-prj]').forEach(tr=>tr.onclick=()=>{PRINTJOB=tr.dataset.prj;render();window.scrollTo(0,0)});
 if(cur){G('prFab').onclick=()=>printSheet(fabricSheetHTML(cur));G('prTna').onclick=()=>printSheet(tnaSheetHTML(cur));G('prChk').onclick=()=>printSheet(bomSheetHTML(cur));G('prCost').onclick=()=>{COSTOPEN=true;render();window.scrollTo(0,0)}}}
